init {
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)

    if ($cmdopts.self) {
        $lib.print("Setting Validin API key for the current user.")
    } else {
        $lib.print("Setting Validin API key for all users.")
    }

    $key_status_ok = $privsep.setValidinAPIKey($cmdopts.apikey, $cmdopts.self)

    if ($key_status_ok) {
        $privsep.debugPrint("Setup", "Validin API key set successfully")
    } else {
        $lib.warn("Failed setting the key for the Validin API. Check if the token you provided is valid.")
    }

}

init {
    $privsep = $lib.import(ex.validin.privsep)

    $privsep.setTagPrefix($cmdopts.tagname)
    $lib.print("Changed the Validin tag prefix to #{p}", p=$privsep.getTagPrefix())
}

init {
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)

    $lib.print("Setting Validin API hostname for all users.")


    $hostname_status_ok = $privsep.setValidinAPIHostname($cmdopts.hostname)
    if ($hostname_status_ok) {
        $privsep.debugPrint("Setup", `Validin API hostname set successfully: {$cmdopts.hostname}`)
    } 

}

init {
    $api = $lib.import(ex.validin.api, debug=$lib.debug)
    $privsep = $lib.import(ex.validin.privsep, debug=$lib.debug)
}

$api_key_set = $privsep.getValidinAPIKey()

if ($api_key_set != $lib.false) {

    switch $node.form() {
        "inet:ipv4": { 
            $data = $api.getIpPDNS($node.repr()) 
            if ($data) {
                divert $cmdopts.yield $privsep.parseIpPDNS($data)
            }
        }
        "inet:fqdn": {
            tee 
            {
                $data = $api.getDomainPDNS($node.repr())
                if ($data) {
                    divert $cmdopts.yield $privsep.parseDomainPDNS($data)
                }
            }
            // If the user requested extra DNS records, fetch them
            // and yield them as well.
            {            
                if ($cmdopts.'include-extra') {
                    $extra_dns = $api.getExtraDomainPDNS($node.repr())
                    if ($extra_dns) {
                        divert $cmdopts.yield $privsep.parseDomainPDNS($extra_dns)
                    }
                }
            }
        }
        *: { if $lib.debug { $lib.warn("unsupported form received: {f}", f=$node.form()) } }
    }

} else {
    $lib.exit("Validin API key not set and is needed to use this function, please run 'ex.validin.setup.apikey' first")
}

